import { z } from 'zod';

// Product Validation
export const createProductSchema = z.object({
  title: z.string().min(2, "የእቃው ስም መገበሪያ አለበት"),
  price: z.string().min(1, "ዋጋ መሞላት አለበት"),
  category: z.string().optional(),
  description: z.string().optional(),
  photoUri: z.string().url("ትክክለኛ የፎቶ ሊንክ ያስገቡ"),
  videoUri: z.string().optional(),
  sellerPhone: z.string().min(10, "ትክክለኛ ስልክ ቁጥር ያስገቡ"),
});

// Shop Validation
export const registerShopSchema = z.object({
  fullName: z.string().min(2),
  phone: z.string().min(10),
  faydaNo: z.string().min(5),
  tinNo: z.string().optional(),
  address: z.string(),
  shopType: z.string(),
  shopDesc: z.string().optional(),
  accountNumber: z.string().min(5),
});

// Checkout Validation
export const checkoutPaymentSchema = z.object({
  productId: z.union([z.string(), z.number()]),
  amount: z.string(),
  paymentMethod: z.string(),
  deliveryTime: z.string(),
  deliveryNote: z.string().optional(),
});
export * from './generated/api';
export * from './generated/types';
